// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;

import java.util.Map;
import java.util.function.UnaryOperator;

import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;

class LmdbDirectAdjacencyOptionsTest {

	private static final long GIB = 1L << 30;

	private static final UnaryOperator<String> NO_PROPERTIES = name -> null;

	@Test
	void directAdjacencyUnsetLimitResolvesToHalfEffectiveXmx() {
		// AUTO resolves once to 50% of the effective JVM max heap, rounded down to eight bytes
		assertThat(LmdbDirectAdjacencyOptions.resolveEffectiveMaxBytes(0, 512 * GIB)).isEqualTo(256 * GIB);
		assertThat(LmdbDirectAdjacencyOptions.resolveEffectiveMaxBytes(0, 64 * GIB)).isEqualTo(32 * GIB);
	}

	@Test
	void autoResolutionRoundsDownToEightByteBoundaryForOddHeaps() {
		// an odd effective heap: half of 1000000007 is 500000003.5 -> 500000003 -> rounded down to 500000000
		assertThat(LmdbDirectAdjacencyOptions.resolveEffectiveMaxBytes(0, 1_000_000_007L))
				.isEqualTo((1_000_000_007L >>> 1) & ~7L);
		assertThat(LmdbDirectAdjacencyOptions.resolveEffectiveMaxBytes(0, 1_000_000_007L) % 8).isZero();
		assertThat(LmdbDirectAdjacencyOptions.resolveEffectiveMaxBytes(0, 15)).isZero();
	}

	@Test
	void explicitLimitOverridesAutoWithoutClamping() {
		// an explicit byte count is authoritative even when it exceeds half (or all) of the JVM heap
		assertThat(LmdbDirectAdjacencyOptions.resolveEffectiveMaxBytes(256 * GIB, 8 * GIB)).isEqualTo(256 * GIB);
	}

	@Test
	void negativeConfiguredLimitIsRejected() {
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbDirectAdjacencyOptions.resolveEffectiveMaxBytes(-1, 8 * GIB));
	}

	@Test
	void autoBelowMinimumMarksMemoryRefusedForNonDisabledMode() {
		LmdbStoreConfig config = new LmdbStoreConfig().setDirectAdjacencyMode(DirectAdjacencyMode.PREFER);
		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(config, 128 * 1024 * 1024,
				NO_PROPERTIES, 8);

		assertThat(options.effectiveMaxBytes()).isLessThan(LmdbDirectAdjacencyOptions.MIN_EXPLICIT_BYTES);
		assertThat(options.memoryRefused()).isTrue();
	}

	@Test
	void autoBelowMinimumIsNotRefusedWhenDisabled() {
		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(new LmdbStoreConfig(),
				128 * 1024 * 1024, NO_PROPERTIES, 8);

		assertThat(options.memoryRefused()).isFalse();
	}

	@Test
	void steadyLimitIsExactIntegerEightySixPercent() {
		// the worked 256-GiB plan constant: 220.16 GiB
		assertThat(LmdbDirectAdjacencyOptions.steadyLimitBytes(256 * GIB)).isEqualTo(236_394_999_971L);
		assertThat(LmdbDirectAdjacencyOptions.steadyLimitBytes(0)).isZero();
		assertThat(LmdbDirectAdjacencyOptions.steadyLimitBytes(100)).isEqualTo(86);
		assertThat(LmdbDirectAdjacencyOptions.steadyLimitBytes(199)).isEqualTo(86 + 85);
		// quotient/remainder arithmetic must not overflow for very large limits
		assertThat(LmdbDirectAdjacencyOptions.steadyLimitBytes(Long.MAX_VALUE / 2)).isPositive();
	}

	@Test
	void defaultCommitCapAppliesFloorComputedValueAndCeiling() {
		// floor: 1 GiB / 1000 is below 8 MiB
		assertThat(LmdbDirectAdjacencyOptions.defaultCommitMaxBytes(GIB))
				.isEqualTo(LmdbDirectAdjacencyOptions.COMMIT_CAP_FLOOR_BYTES);
		// computed: 32 GiB / 1000
		assertThat(LmdbDirectAdjacencyOptions.defaultCommitMaxBytes(32 * GIB)).isEqualTo(32 * GIB / 1000);
		// ceiling: 256 GiB / 1000 exceeds 64 MiB
		assertThat(LmdbDirectAdjacencyOptions.defaultCommitMaxBytes(256 * GIB))
				.isEqualTo(LmdbDirectAdjacencyOptions.DEFAULT_COMMIT_CAP_CEILING_BYTES);
	}

	@Test
	void absoluteCommitCapAppliesFloorComputedValueAndCeiling() {
		// floor: 512 MiB / 100 is below 8 MiB
		assertThat(LmdbDirectAdjacencyOptions.absoluteCommitMaxBytes(512L * 1024 * 1024))
				.isEqualTo(LmdbDirectAdjacencyOptions.COMMIT_CAP_FLOOR_BYTES);
		assertThat(LmdbDirectAdjacencyOptions.absoluteCommitMaxBytes(32 * GIB)).isEqualTo(32 * GIB / 100);
		assertThat(LmdbDirectAdjacencyOptions.absoluteCommitMaxBytes(256 * GIB))
				.isEqualTo(LmdbDirectAdjacencyOptions.ABSOLUTE_COMMIT_CAP_CEILING_BYTES);
	}

	@Test
	void explicitCommitCapMayLowerOrRaiseTheDefaultWithinTheAbsoluteCeiling() {
		long maxBytes = 256 * GIB;
		// lower than the 64-MiB default
		assertThat(LmdbDirectAdjacencyOptions.resolveCommitMaxBytes("16777216", maxBytes)).isEqualTo(16_777_216L);
		// raised above the default but below the 2-GiB absolute ceiling
		assertThat(LmdbDirectAdjacencyOptions.resolveCommitMaxBytes("1073741824", maxBytes)).isEqualTo(GIB);
		// unset uses the default
		assertThat(LmdbDirectAdjacencyOptions.resolveCommitMaxBytes(null, maxBytes))
				.isEqualTo(LmdbDirectAdjacencyOptions.defaultCommitMaxBytes(maxBytes));
	}

	@Test
	void explicitCommitCapRejectsZeroNegativeAndOverCeilingValues() {
		long maxBytes = 256 * GIB;
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbDirectAdjacencyOptions.resolveCommitMaxBytes("0", maxBytes));
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbDirectAdjacencyOptions.resolveCommitMaxBytes("-1", maxBytes));
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbDirectAdjacencyOptions.resolveCommitMaxBytes("2147483649", maxBytes));
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbDirectAdjacencyOptions.resolveCommitMaxBytes("not-a-number", maxBytes));
	}

	@Test
	void resolveCollectsTuningPropertiesOnce() {
		Map<String, String> properties = Map.of(
				LmdbDirectAdjacencyOptions.COMMIT_MAX_BYTES_PROPERTY, "33554432",
				LmdbDirectAdjacencyOptions.SEAL_WARN_MILLIS_PROPERTY, "2000",
				LmdbDirectAdjacencyOptions.MAX_DELTA_GENERATIONS_PROPERTY, "4",
				LmdbDirectAdjacencyOptions.BUILD_THREADS_PROPERTY, "2");
		LmdbStoreConfig config = new LmdbStoreConfig()
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(256 * GIB);

		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(config, 8 * GIB, properties::get, 16);

		assertThat(options.mode()).isEqualTo(DirectAdjacencyMode.PREFER);
		assertThat(options.requestedMaxBytes()).isEqualTo(256 * GIB);
		assertThat(options.effectiveMaxBytes()).isEqualTo(256 * GIB);
		assertThat(options.steadyLimitBytes()).isEqualTo(236_394_999_971L);
		assertThat(options.memoryRefused()).isFalse();
		assertThat(options.commitMaxBytes()).isEqualTo(33_554_432L);
		assertThat(options.sealWarnMillis()).isEqualTo(2000L);
		assertThat(options.maxDeltaGenerations()).isEqualTo(4);
		assertThat(options.buildThreads()).isEqualTo(2);
		assertThat(options.supernodeEdges()).isEqualTo(1_048_576L);
		assertThat(options.supernodeChunkEdges()).isEqualTo(65_536L);
		assertThat(options.supernodeTargetBytes()).isEqualTo(67_108_864L);
		assertThat(options.buildTargetMillis()).isEqualTo(43_200_000L);
		assertThat(options.buildRetryMillis()).isEqualTo(60_000L);
		assertThat(options.shadowSampleEvery()).isEqualTo(10_000L);
	}

	@Test
	void buildThreadsDefaultToProcessorBoundedFourAndRejectOutOfRangeValues() {
		LmdbStoreConfig config = new LmdbStoreConfig();

		assertThat(LmdbDirectAdjacencyOptions.resolve(config, 8 * GIB, NO_PROPERTIES, 16).buildThreads()).isEqualTo(4);
		assertThat(LmdbDirectAdjacencyOptions.resolve(config, 8 * GIB, NO_PROPERTIES, 2).buildThreads()).isEqualTo(2);

		Map<String, String> tooMany = Map.of(LmdbDirectAdjacencyOptions.BUILD_THREADS_PROPERTY, "5");
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbDirectAdjacencyOptions.resolve(config, 8 * GIB, tooMany::get, 16));
		Map<String, String> tooFew = Map.of(LmdbDirectAdjacencyOptions.BUILD_THREADS_PROPERTY, "0");
		assertThatIllegalArgumentException()
				.isThrownBy(() -> LmdbDirectAdjacencyOptions.resolve(config, 8 * GIB, tooFew::get, 16));
	}
}
